import{_ as a,o,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const v=JSON.parse('{"title":"Reutilize e revise variáveis de execução","description":"","frontmatter":{"title":"Reutilize e revise variáveis de execução","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"d20bdf1421e729be7924c171ad9418c14ce948d1021fcf443aa7f09cc8b2fc4d","order":40},"headers":[],"relativePath":"pt/user/automations/variables.md","filePath":"pt/user/automations/variables.md","lastUpdated":1794611623000}'),t={name:"pt/user/automations/variables.md"};function i(d,e,l,c,n,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Reutilize e revise variáveis de execução <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;Reutilize e revise variáveis de execução {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Altere um valor compartilhado uma vez e reutilize-o em várias ações. Você precisa de <strong>Automations → Variables</strong> e de um host compatível com as operações de variáveis relevantes. A edição tipada e as operações revisadas do Cloud aparecem conforme as capacidades do host; salvar localmente não exige envio.</p><h2 id="save-a-local-value" tabindex="-1">Salve um valor local <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;Salve um valor local {#save-a-local-value}&quot;">​</a></h2><ol><li>Adicione uma variável chamada <code>showLabel</code>. As chaves começam com uma letra ou sublinhado e podem conter letras, dígitos, pontos, sublinhados e hifens, até <code>64</code> caracteres. Evite chaves duplicadas.</li><li>Quando a edição tipada estiver disponível, escolha texto e digite <code>Programa da noite</code>. Outros tipos aceitos são número, booleano, lista e segredo. Listas usam um array JSON de strings, como <code>[&quot;vermelho&quot;, &quot;azul&quot;]</code>.</li><li>Selecione <strong>Save</strong>. Um conflito de revisão significa que a coleção salva mudou; recarregue e revise a edição pretendida em relação a ela.</li><li>Use o valor salvo em um campo de ação com modelo:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Teste uma ação apenas de registro para inspecionar o texto renderizado. Altere <code>showLabel</code>, salve novamente e execute um novo teste. As definições de ações existentes podem reutilizar o valor atualizado sem reimportar um modelo.</li></ol><p>Os <code>params</code> do modelo são substituídos na aplicação do modelo; <code>globals</code> são lidos na execução. Uma chave ausente em tempo de execução é renderizada como texto vazio, portanto confira a grafia antes de usá-la em um destino ou identificador. Use as sugestões de variáveis do campo para caminhos de evento adequados ao seu acionador.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Revise alterações do Cloud separadamente <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;Revise alterações do Cloud separadamente {#review-cloud-changes-separately}&quot;">​</a></h2><p>O controle <strong>Changes</strong> de Variables tem operações nativas revisadas de enviar, buscar, aplicar/adotar e retirar quando compatíveis. Salve as edições locais primeiro, selecione uma comparação, inspecione seu tipo e valor e escolha explicitamente a direção desejada. Buscar uma candidata do Cloud é separado de aplicá-la localmente. Retirar um valor compartilhado é separado de excluir uma linha local.</p><p>Valores secretos ou bloqueados ficam mascarados nas comparações e não podem ser enviados por esse caminho revisado. Nunca transforme um segredo em texto comum apenas para contornar esse bloqueio.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, status e recuperação {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Variáveis locais e compartilhamento revisado condicionado às capacidades estão disponíveis; salvar localmente nunca envia automaticamente. Chaves inválidas, valores tipados inválidos e revisões desatualizadas bloqueiam o salvamento. Corrija o campo destacado ou recarregue antes de tentar novamente. Para falhas de conta, consulte <a href="./../cloud/account.html">conta do Cloud</a>; para o comportamento de comparação, consulte <a href="./../cloud/changes.html">Changes</a>.</p>',13)])])}const p=a(t,[["render",i]]);export{v as __pageData,p as default};
